import{_ as o,o as d,c as p,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const T=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-Summary-Functions-for-Individual-Cells.md","filePath":"manual-zh/CTABLES-Summary-Functions-for-Individual-Cells.md","lastUpdated":1785684581000}'),a={name:"manual-zh/CTABLES-Summary-Functions-for-Individual-Cells.md"};function r(n,e,i,t,s,l){return d(),p("div",null,[...e[0]||(e[0]=[c('<h4 id="_15-7-2-1-针对单个单元格的汇总函数" tabindex="-1">15.7.2.1 针对单个单元格的汇总函数 <a class="header-anchor" href="#_15-7-2-1-针对单个单元格的汇总函数" aria-label="Permalink to &quot;15.7.2.1 针对单个单元格的汇总函数&quot;">​</a></h4><p>本节列出了只考虑 <code>CTABLES</code> 中单个单元格的汇总函数。只有一个这样的汇总函数 <code>COUNT</code> 可同时应用于分类变量和标度变量：</p><p><code>COUNT</code>（“Count”，F40.0）</p><p>单元格中权重之和。</p><p>如果表中一个或多个变量的 <code>CATEGORIES</code> 包含缺失值（参见 <a href="./CTABLES-Per_002dVariable-Category-Options">CTABLES 各变量类别选项</a>），则一个单元格的部分或全部类别可能是缺失值。<code>COUNT</code> 会对单元格中包含的数据进行计数，无论其类别是否为缺失值。</p><p>下列汇总函数仅适用于标度变量，或分类变量的合计与小计。对于后者，解释汇总值时要谨慎，因为它未必有意义；不过，诸如李克特量表（Likert scale）的均值等可能具有直观的解释。</p><p><code>MAXIMUM</code>（“Maximum”）</p><p>最大值。</p><p><code>MEAN</code>（“Mean”）</p><p>均值。</p><p><code>MEDIAN</code>（“Median”）</p><p>中位数值。</p><p><code>MINIMUM</code>（“Minimum”）</p><p>最小值。</p><p><code>MISSING</code>（“Missing”）</p><p>用户缺失值与系统缺失值的权重之和。</p><p><code>MODE</code>（“Mode”）</p><p>出现频率最高的值。出现并列时，取最小的众数。</p><p><code>PTILE</code> <em>n</em>（“Percentile <em>n</em> ”）</p><p>第 n 个百分位数，其中 <em>0 ≤ n ≤ 100</em>。</p><p><code>RANGE</code>（“Range”）</p><p>最大值减去最小值。</p><p><code>SEMEAN</code>（“Std Error of Mean”）</p><p>均值的标准误。</p><p><code>STDDEV</code>（“Std Deviation”）</p><p>标准差。</p><p><code>SUM</code>（“Sum”）</p><p>总和。</p><p><code>TOTALN</code>（“Total N”，F40.0）</p><p>单元格中权重之和。</p><p>对标度数据而言，<code>COUNT</code> 与 <code>TOTALN</code> 相同。</p><p>对分类数据而言，<code>TOTALN</code> 会统计被排除类别中的缺失值，即在 <code>CATEGORIES</code> 的显式类别列表中不存在的用户缺失值（参见 <a href="./CTABLES-Per_002dVariable-Category-Options">CTABLES 各变量类别选项</a>）、因 <code>CATEGORIES</code> 中 <code>MISSING=EXCLUDE</code> 生效而被排除的用户缺失值，以及系统缺失值。<code>COUNT</code> 不统计这些。</p><p>有关 <code>CTABLES</code> 如何汇总缺失值的细节，请参见 <a href="./CTABLES-Missing-Values-for-Summary-Variables">CTABLES 汇总变量的缺失值</a>。</p><p><code>VALIDN</code>（“Valid N”，F40.0）</p><p>所包含类别中有效计数权重之和。</p><p>对分类变量而言，无论缺失值是否通过 <code>CATEGORIES</code> 包含在类别中，<code>VALIDN</code> 都不统计缺失值。<code>VALIDN</code> 也不统计处于被排除类别中的有效值。细节请参见 <a href="./CTABLES-Missing-Values-for-Summary-Variables">CTABLES 汇总变量的缺失值</a>。</p><p><code>VARIANCE</code>（“Variance”）</p><p>方差。</p>',38)])])}const m=o(a,[["render",r]]);export{T as __pageData,m as default};
